{"code":"import random

def generate(rng):
    h = rng.randint(7, 14); w = rng.randint(7, 14)
    g = [[0]*w for _ in range(h)]
    n = rng.randint(3, 6)
    for _ in range(n):
        # separated simple objects: line (the likely class-2 object) or compact block/shape (class-8)
        typ = rng.choice(['vline','hline','block','lshape'])
        color = 5
        for attempt in range(30):
            r = rng.randrange(1, h-4); c = rng.randrange(1, w-4)
            if typ == 'vline':
                cells=[(r+i,c) for i in range(rng.randint(2,4))]
            elif typ == 'hline':
                cells=[(r,c+i) for i in range(rng.randint(2,4))]
            elif typ == 'block':
                hh=rng.randint(2,3); ww=rng.randint(2,3)
                cells=[(r+i,c+j) for i in range(hh) for j in range(ww)]
            else:
                cells=[(r,c),(r+1,c),(r+1,c+1),(r+1,c+2),(r+2,c+2)]
            if all(0<=x<h and 0<=y<w and g[x][y]==0 for x,y in cells):
                # keep objects non-touching, including diagonal spacing
                around={(x+dx,y+dy) for x,y in cells for dx in (-1,0,1) for dy in (-1,0,1)}
                occupied={(x,y) for x in range(h) for y in range(w) if g[x][y]}
                if not around & occupied:
                    for x,y in cells:g[x][y]=color
                    break
    return g"}

